    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        miTaxi = new Taxi("andj", 50.0);
        txtConsola.append("Taxi inicializado correctamente.\n");
        txtConsola.append(miTaxi.generarTicket() + "\n\n");
    }//GEN-LAST:event_jButton1ActionPerformed

    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
        if (miTaxi == null) {
            txtConsola.append("Error: Primero debes iniciar el turno.\n");
            return;
        }

        try {
            // Obtenemos los kilómetros ingresados y los convertimos a número
            int kms = Integer.parseInt(txtKilometros.getText());
            miTaxi.registrarViaje();
            
            // Llamada al MÉTODO RECURSIVO del TDA
            double costoTotal = miTaxi.calcularCostoRecursivo(kms, miTaxi.getTarifaBase());
            
            txtConsola.append("--- TICKET DE VIAJE ---\n");
            txtConsola.append("Distancia: " + kms + " km\n");
            txtConsola.append("Total a cobrar: $" + costoTotal + "\n\n");
            txtConsola.append(miTaxi.generarTicket() + "\n\n");
            
        } catch (NumberFormatException ex) {
            txtConsola.append("Error: Ingresa un número válido de kilómetros.\n");
        }
    }//GEN-LAST:event_jButton2ActionPerformed

